				<div class="elementor-element elementor-element-6065af8 e-con-full e-flex e-con e-parent" data-id="6065af8" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[],&quot;background_background&quot;:&quot;classic&quot;}">
